* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: #f4f6f8;
  color: #141821;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

.partner-overview {
  min-height: 100vh;
  padding: 22px;
  background: #f4f6f8;
}

.overview-header {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-start;
  margin-bottom: 18px;
}

.overview-header p {
  margin: 0 0 4px;
  color: #2257d6;
  font-size: 13px;
  font-weight: 900;
  text-transform: uppercase;
}

.overview-header h1 {
  margin: 0;
  font-size: 34px;
  letter-spacing: 0;
}

.overview-header span {
  display: block;
  margin-top: 6px;
  color: #647085;
  font-weight: 700;
}

.overview-header button {
  border: 0;
  min-height: 40px;
  padding: 0 16px;
  border-radius: 6px;
  background: #141b31;
  color: white;
  font-weight: 900;
  cursor: pointer;
}

.kpis {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin-bottom: 14px;
}

.kpis article {
  background: white;
  border: 1px solid #dce4ef;
  border-radius: 8px;
  padding: 18px;
  min-height: 112px;
  box-shadow: 0 8px 28px rgba(22, 34, 54, 0.07);
  display: grid;
  gap: 8px;
}

.kpis span {
  color: #647085;
  font-weight: 800;
}

.kpis strong {
  font-size: 26px;
  line-height: 1;
}

.summary-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.panel {
  background: white;
  border: 1px solid #dce4ef;
  border-radius: 8px;
  padding: 18px;
  box-shadow: 0 8px 28px rgba(22, 34, 54, 0.06);
}

.panel.wide {
  grid-column: span 2;
}

.panel-title {
  margin-bottom: 14px;
}

.panel-title h2 {
  margin: 0;
  font-size: 18px;
}

.panel-title span {
  display: block;
  margin-top: 4px;
  color: #69768a;
  font-size: 13px;
  font-weight: 700;
}

.split {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

.split div {
  min-height: 86px;
  border: 1px solid #e3e9f2;
  border-radius: 8px;
  background: #f8fafc;
  padding: 14px;
  display: grid;
  align-content: center;
  gap: 5px;
}

.split b {
  font-size: 22px;
}

.split span {
  color: #69768a;
  font-size: 12px;
  font-weight: 800;
}

.list {
  display: grid;
  gap: 10px;
}

.list-row {
  min-height: 58px;
  padding: 12px;
  border: 1px solid #e2e8f0;
  border-radius: 7px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.list-row strong,
.partner-card strong {
  display: block;
  font-size: 14px;
}

.list-row span,
.partner-card span,
td span {
  display: block;
  margin-top: 3px;
  color: #6b778a;
  font-size: 12px;
  font-weight: 700;
}

.list-row b {
  white-space: nowrap;
}

.partner-cards {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.partner-card {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) 120px;
  align-items: center;
  gap: 12px;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 12px;
}

.rank {
  width: 34px;
  height: 34px;
  border-radius: 6px;
  display: grid;
  place-items: center;
  background: #141b31;
  color: white;
  font-weight: 900;
}

.partner-card b {
  text-align: right;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th,
td {
  border-bottom: 1px solid #e6ecf4;
  padding: 11px 10px;
  text-align: left;
  font-size: 13px;
}

th {
  background: #f8fafc;
  color: #445066;
  font-weight: 900;
}

td strong {
  display: block;
}

em {
  display: inline-flex;
  border-radius: 999px;
  padding: 4px 8px;
  font-style: normal;
  font-size: 11px;
  font-weight: 900;
}

em.success {
  background: #dcfce7;
  color: #166534;
}

em.warning {
  background: #fef3c7;
  color: #92400e;
}

em.danger {
  background: #fee2e2;
  color: #991b1b;
}

em.info {
  background: #dbeafe;
  color: #1e40af;
}

.empty {
  padding: 30px 14px;
  color: #7a8495;
  font-weight: 800;
  text-align: center;
  border: 1px dashed #d7dee9;
  border-radius: 8px;
  background: #f8fafc;
}

footer {
  margin-top: 16px;
  color: #6d788a;
  font-size: 12px;
  font-weight: 700;
}

@media print {
  .no-print {
    display: none !important;
  }
  body,
  .partner-overview {
    background: white;
  }
  .partner-overview {
    padding: 0;
  }
  .panel,
  .kpis article {
    box-shadow: none;
    break-inside: avoid;
  }
}

